    .deal-card {
      grid-template-columns: 0.95fr 1.05fr;
    }

    .deal-visual {
      min-height: 100%;
      padding: 1rem;
      display: grid;
      align-content: space-between;
      background:
        radial-gradient(circle at 20% 30%, rgba(255, 184, 107, 0.35), transparent 28%),
