    const featuredProducts = [
      {
        name: 'Luna Desk Lamp',
        category: 'Lighting',
        price: '$64',
        oldPrice: '$78',
        badge: 'Best seller',
        accent: 'rgba(143, 211, 255, 0.34)',
        symbol: 'L',
        description: 'Soft ambient light with a weighted base and touch dimmer.',
