      },
    ];

    const featuredGrid = document.getElementById('featuredGrid');
    const dealGrid = document.getElementById('dealGrid');
    const storyGrid = document.getElementById('storyGrid');
    const statusMessage = document.getElementById('statusMessage');
    const cartCount = document.getElementById('cartCount');
    const cartStatus = document.getElementById('cartStatus');
    const year = document.getElementById('year');
    let bagCount = 0;

    function updateBag(delta, label) {
      bagCount += delta;
      cartCount.textContent = String(bagCount);
      cartStatus.textContent = `${bagCount} item${bagCount === 1 ? '' : 's'} in bag`;
      statusMessage.textContent = `${label} added to bag. ${bagCount} item${bagCount === 1 ? '' : 's'} total.`;
    }

