          <div class="product-art" aria-hidden="true"><span>${product.symbol}</span></div>
        </div>
        <div class="card-body">
          <div>
            <h3>${product.name}</h3>
            <p class="meta">${product.description}</p>
          </div>
          <div class="price-row">
            <p class="price">${product.price} <span class="old-price">${product.oldPrice}</span></p>
            <div class="product-actions">
              <button class="button button-primary" type="button">Add to bag</button>
              <a class="button button-secondary" href="#stories">Details</a>
            </div>
          </div>
        </div>
      `;

      article.querySelector('button').addEventListener('click', () => updateBag(1, product.name));
      return article;
    }

    function createDealCard(deal) {
      const article = document.createElement('article');
      article.className = 'card deal-card';
      article.innerHTML = `
        <div class="deal-visual" style="--glow: ${deal.accent}">
          <span class="stamp">${deal.label}</span>
          <div class="countdown">${deal.price}</div>
        </div>
        <div class="card-body">
          <div>
            <h3>${deal.title}</h3>
            <p class="meta">${deal.summary}</p>
          </div>
          <div class="price-row">
            <p class="meta"><strong>${deal.detail}</strong></p>
            <button class="button button-primary" type="button">Shop deal</button>
          </div>
        </div>
      `;

      article.querySelector('button').addEventListener('click', () => updateBag(1, deal.title));
      return article;
    }

    function createStoryCard(story) {
      const article = document.createElement('article');
      article.className = 'card story-card';
      article.innerHTML = `
        <div class="card-body">
          <span class="story-kicker">${story.kicker}</span>
          <h3>${story.title}</h3>
          <p class="meta">${story.body}</p>
          <a class="button button-secondary" href="#featured">Explore products</a>
        </div>
      `;
      return article;
    }

    featuredProducts.forEach((product) => featuredGrid.appendChild(createFeatureCard(product)));
    deals.forEach((deal) => dealGrid.appendChild(createDealCard(deal)));
    stories.forEach((story) => storyGrid.appendChild(createStoryCard(story)));

    year.textContent = new Date().getFullYear();
