<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <header class="site-header">
    <div class="page-shell header-inner">
      <a class="brand" href="#top" aria-label="Nova Retail home">
        <span class="brand-mark" aria-hidden="true">N</span>
        <span class="brand-copy">
          Nova Retail
          <span>Modern essentials for home and lifestyle</span>
        </span>
      </a>

      <nav class="site-nav" aria-label="Primary">
        <a href="#featured">Featured</a>
        <a href="#deals">Deals</a>
        <a href="#stories">Stories</a>
      </nav>

      <div class="cart-chip" aria-labelledby="bagLabel cartStatus">
        <span id="bagLabel" aria-hidden="true">Bag</span>
        <span class="cart-badge" id="cartCount" aria-hidden="true">0</span>
        <span class="sr-only" id="cartStatus">0 items in bag</span>
      </div>
    </div>
  </header>

  <main id="maincontent" class="page-shell" tabindex="-1">
    <section class="hero" aria-labelledby="home-title">
      <div class="hero-copy">
        <p class="eyebrow">New season edit · Dark luxury collection</p>
        <h1 id="home-title">Elevated pieces for everyday rituals.</h1>
        <p>
          Discover warm lighting, soft textures, and smart essentials curated to make
          the home feel calmer, sharper, and easier to live in.
        </p>
        <div class="hero-actions">
          <a class="button button-primary" href="#featured">Shop featured products</a>
          <a class="button button-secondary" href="#stories">Read the editorial</a>
        </div>
        <dl class="hero-stats" aria-label="Store highlights">
          <div>
            <dt>New arrivals</dt>
            <dd>24</dd>
          </div>
          <div>
            <dt>Dispatch</dt>
            <dd>48h</dd>
          </div>
          <div>
            <dt>Rating</dt>
            <dd>4.9/5</dd>
          </div>
        </dl>
      </div>

      <aside class="hero-panel" aria-label="Featured spotlight">
        <div class="panel-grid">
          <div class="mini-banner">
            <div>
              <strong>Members get early access</strong>
              <span>Save on the first drop of the week</span>
            </div>
            <span class="chip">Up to 30% off</span>
          </div>

          <div class="ornament">
            <div class="ornament-content">
              <div class="price-tag">Bundle from $89</div>
              <h2>Ambient lighting set</h2>
              <p>Layered glow, low-profile design, and a five-hour dimmable battery.</p>
              <a class="button button-primary" href="#deals">See the deal</a>
            </div>
          </div>

          <div class="mini-banner">
            <div>
              <strong>Free returns on every order</strong>
              <span>Try it at home for 30 days</span>
            </div>
            <span class="chip">No risk</span>
          </div>
        </div>
      </aside>
    </section>

    <section class="section" id="featured" aria-labelledby="featured-title">
      <div class="section-header">
        <div>
          <h2 id="featured-title">Featured products</h2>
          <p>Hero items selected for the homepage — refined materials, clean silhouettes, and everyday function.</p>
        </div>
      </div>
      <div class="grid featured-grid" id="featuredGrid"></div>
    </section>

    <section class="section" id="deals" aria-labelledby="deals-title">
      <div class="section-header">
        <div>
          <h2 id="deals-title">Today's deals</h2>
          <p>Limited-time bundles and discounts with a strong visual hierarchy so the savings are easy to scan.</p>
        </div>
      </div>
      <div class="grid deal-grid" id="dealGrid"></div>
    </section>

    <section class="section" id="stories" aria-labelledby="stories-title">
      <div class="section-header">
        <div>
          <h2 id="stories-title">Editorial stories</h2>
          <p>Short-form inspiration that connects the product mix to lifestyle, care tips, and seasonal styling.</p>
        </div>
      </div>
      <div class="grid editorial-grid" id="storyGrid"></div>
    </section>

    <p class="status-bar" id="statusMessage" aria-live="polite">Ready to shop.</p>
  </main>

  <footer class="site-footer">
    <div class="page-shell footer-inner">
      <span>&copy; <span id="year"></span> Nova Retail</span>
      <span>Dark visual style · Plain HTML, CSS, and JavaScript</span>
    </div>
  </footer>

  <script>
    const featuredProducts = [
      {
        name: 'Luna Desk Lamp',
        category: 'Lighting',
        price: '$64',
        oldPrice: '$78',
        badge: 'Best seller',
        accent: 'rgba(143, 211, 255, 0.34)',
        symbol: 'L',
        description: 'Soft ambient light with a weighted base and touch dimmer.',
      },
      {
        name: 'Terra Throw Set',
        category: 'Textiles',
        price: '$92',
        oldPrice: '$110',
        badge: 'New',
        accent: 'rgba(123, 228, 149, 0.32)',
        symbol: 'T',
        description: 'Brushed layers in charcoal and slate for a richer sofa look.',
      },
      {
        name: 'Halo Organizer',
        category: 'Storage',
        price: '$38',
        oldPrice: '$46',
        badge: 'Staff pick',
        accent: 'rgba(255, 184, 107, 0.32)',
        symbol: 'H',
        description: 'A compact tray system for keys, charging, and daily carry.',
      },
    ];

    const deals = [
      {
        title: 'Weekend bundle',
        label: 'Save 25%',
        summary: 'Pair a lamp, tray, and candle for a complete bedside refresh.',
        price: '$129',
        detail: 'Normally $172',
        accent: 'rgba(255, 184, 107, 0.36)',
      },
      {
        title: 'Members-only markdown',
        label: 'Save 20%',
        summary: 'Smart storage pieces for hallways, desks, and entryways.',
        price: '$56',
        detail: 'Ends tonight',
        accent: 'rgba(143, 211, 255, 0.34)',
      },
    ];

    const stories = [
      {
        kicker: 'Editorial',
        title: 'How to style a low-light living room',
        body: 'Use layered lamps, dark woods, and one bright focal accent to keep a moody room welcoming instead of flat.',
      },
      {
        kicker: 'Guide',
        title: 'The five-minute reset for an uncluttered entryway',
        body: 'A tray, a hook, and a catchall can make daily routines easier without changing the footprint of the space.',
      },
      {
        kicker: 'Trend report',
        title: 'Why tactile surfaces are back',
        body: 'Soft-touch finishes and matte ceramics add warmth to minimal spaces while staying practical to maintain.',
      },
    ];

    const featuredGrid = document.getElementById('featuredGrid');
    const dealGrid = document.getElementById('dealGrid');
    const storyGrid = document.getElementById('storyGrid');
    const statusMessage = document.getElementById('statusMessage');
    const cartCount = document.getElementById('cartCount');
    const cartStatus = document.getElementById('cartStatus');
    const year = document.getElementById('year');
    let bagCount = 0;

    function updateBag(delta, label) {
      bagCount += delta;
      cartCount.textContent = String(bagCount);
      cartStatus.textContent = `${bagCount} item${bagCount === 1 ? '' : 's'} in bag`;
      statusMessage.textContent = `${label} added to bag. ${bagCount} item${bagCount === 1 ? '' : 's'} total.`;
    }

    function createFeatureCard(product) {
      const article = document.createElement('article');
      article.className = 'card product-card';
      article.innerHTML = `
        <div class="visual" style="--glow: ${product.accent}">
          <div class="chip-row">
            <span class="chip">${product.badge}</span>
            <span class="chip">${product.category}</span>
          </div>
          <div class="product-art" aria-hidden="true"><span>${product.symbol}</span></div>
        </div>
        <div class="card-body">
          <div>
            <h3>${product.name}</h3>
            <p class="meta">${product.description}</p>
          </div>
          <div class="price-row">
            <p class="price">${product.price} <span class="old-price">${product.oldPrice}</span></p>
            <div class="product-actions">
              <button class="button button-primary" type="button">Add to bag</button>
              <a class="button button-secondary" href="#stories">Details</a>
            </div>
          </div>
        </div>
      `;

      article.querySelector('button').addEventListener('click', () => updateBag(1, product.name));
      return article;
    }

    function createDealCard(deal) {
      const article = document.createElement('article');
      article.className = 'card deal-card';
      article.innerHTML = `
        <div class="deal-visual" style="--glow: ${deal.accent}">
          <span class="stamp">${deal.label}</span>
          <div class="countdown">${deal.price}</div>
        </div>
        <div class="card-body">
          <div>
            <h3>${deal.title}</h3>
            <p class="meta">${deal.summary}</p>
          </div>
          <div class="price-row">
            <p class="meta"><strong>${deal.detail}</strong></p>
            <button class="button button-primary" type="button">Shop deal</button>
          </div>
        </div>
      `;

      article.querySelector('button').addEventListener('click', () => updateBag(1, deal.title));
      return article;
    }

    function createStoryCard(story) {
      const article = document.createElement('article');
      article.className = 'card story-card';
      article.innerHTML = `
        <div class="card-body">
          <span class="story-kicker">${story.kicker}</span>
          <h3>${story.title}</h3>
          <p class="meta">${story.body}</p>
          <a class="button button-secondary" href="#featured">Explore products</a>
        </div>
      `;
      return article;
    }

    featuredProducts.forEach((product) => featuredGrid.appendChild(createFeatureCard(product)));
    deals.forEach((deal) => dealGrid.appendChild(createDealCard(deal)));
    stories.forEach((story) => storyGrid.appendChild(createStoryCard(story)));

    year.textContent = new Date().getFullYear();
  </script>
</body>
</html>
