   <script>
     const featuredProducts = [
       {
         name: 'Luna Desk Lamp',
         category: 'Lighting',
         price: '$64',
         oldPrice: '$78',
         badge: 'Best seller',
         accent: 'rgba(143, 211, 255, 0.34)',
         symbol: 'L',
         description: 'Soft ambient light with a weighted base and touch dimmer.',
       },
       {
         name: 'Terra Throw Set',
         category: 'Textiles',
         price: '$92',
         oldPrice: '$110',
         badge: 'New',
         accent: 'rgba(123, 228, 149, 0.32)',
         symbol: 'T',
         description: 'Brushed layers in charcoal and slate for a richer sofa look.',
       },
       {
         name: 'Halo Organizer',
         category: 'Storage',
         price: '$38',
         oldPrice: '$46',
         badge: 'Staff pick',
         accent: 'rgba(255, 184, 107, 0.32)',
         symbol: 'H',
         description: 'A compact tray system for keys, charging, and daily carry.',
       },
     ];

     const deals = [
       {
         title: 'Weekend bundle',
         label: 'Save 25%',
         summary: 'Pair a lamp, tray, and candle for a complete bedside refresh.',
         price: '$129',
         detail: 'Normally $172',
         accent: 'rgba(255, 184, 107, 0.36)',
       },
       {
         title: 'Members-only markdown',
         label: 'Save 20%',
         summary: 'Smart storage pieces for hallways, desks, and entryways.',
         price: '$56',
         detail: 'Ends tonight',
         accent: 'rgba(143, 211, 255, 0.34)',
       },
     ];

     const stories = [
       {
         kicker: 'Editorial',
         title: 'How to style a low-light living room',
         body: 'Use layered lamps, dark woods, and one bright focal accent to keep a moody room welcoming instead of flat.',
       },
       {
         kicker: 'Guide',
         title: 'The five-minute reset for an uncluttered entryway',
         body: 'A tray, a hook, and a catchall can make daily routines easier without changing the footprint of the space.',
       },
       {
         kicker: 'Trend report',
         title: 'Why tactile surfaces are back',
         body: 'Soft-touch finishes and matte ceramics add warmth to minimal spaces while staying practical to maintain.',
       },
     ];

     const featuredGrid = document.getElementById('featuredGrid');
     const dealGrid = document.getElementById('dealGrid');
     const storyGrid = document.getElementById('storyGrid');
     const statusMessage = document.getElementById('statusMessage');
     const cartCount = document.getElementById('cartCount');
     const cartStatus = document.getElementById('cartStatus');
     const year = document.getElementById('year');
     let bagCount = 0;

     function updateBag(delta, label) {
       bagCount += delta;
       cartCount.textContent = String(bagCount);
       cartStatus.textContent = `${bagCount} item${bagCount === 1 ? '' : 's'} in bag`;
       statusMessage.textContent = `${label} added to bag. ${bagCount} item${bagCount === 1 ? '' : 's'} total.`;
     }

     function createFeatureCard(product) {
       const article = document.createElement('article');
       article.className = 'card product-card';
       article.innerHTML = `
         <div class="visual" style="--glow: ${product.accent}">
           <div class="chip-row">
             <span class="chip">${product.badge}</span>
             <span class="chip">${product.category}</span>
           </div>
           <div class="product-art" aria-hidden="true"><span>${product.symbol}</span></div>
         </div>
         <div class="card-body">
           <div>
             <h3>${product.name}</h3>
             <p class="meta">${product.description}</p>
           </div>
           <div class="price-row">
             <p class="price">${product.price} <span class="old-price">${product.oldPrice}</span></p>
             <div class="product-actions">
               <button class="button button-primary" type="button">Add to bag</button>
               <a class="button button-secondary" href="#stories">Details</a>
             </div>
           </div>
         </div>
       `;

       article.querySelector('button').addEventListener('click', () => updateBag(1, product.name));
       return article;
     }

     function createDealCard(deal) {
       const article = document.createElement('article');
       article.className = 'card deal-card';
       article.innerHTML = `
         <div class="deal-visual" style="--glow: ${deal.accent}">
           <span class="stamp">${deal.label}</span>
           <div class="countdown">${deal.price}</div>
         </div>
         <div class="card-body">
           <div>
             <h3>${deal.title}</h3>
             <p class="meta">${deal.summary}</p>
           </div>
           <div class="price-row">
             <p class="meta"><strong>${deal.detail}</strong></p>
             <button class="button button-primary" type="button">Shop deal</button>
           </div>
         </div>
       `;

       article.querySelector('button').addEventListener('click', () => updateBag(1, deal.title));
       return article;
     }

     function createStoryCard(story) {
       const article = document.createElement('article');
       article.className = 'card story-card';
       article.innerHTML = `
         <div class="card-body">
           <span class="story-kicker">${story.kicker}</span>
           <h3>${story.title}</h3>
           <p class="meta">${story.body}</p>
           <a class="button button-secondary" href="#featured">Explore products</a>
         </div>
       `;
       return article;
     }

     featuredProducts.forEach((product) => featuredGrid.appendChild(createFeatureCard(product)));
     deals.forEach((deal) => dealGrid.appendChild(createDealCard(deal)));
     stories.forEach((story) => storyGrid.appendChild(createStoryCard(story)));

     year.textContent = new Date().getFullYear();
   </script>
 </body>
 </html>

')
